/* Reference composition: left-hand proposition, luminous workflow, five stations. */
:is(h1, h2, h3, h4, h5, h6) .heading-last-word {
  color: #7a2c82;
  -webkit-text-fill-color: #7a2c82;
}
.hero :is(h1, h2, h3, h4, h5, h6) .heading-last-word {
  color: #b794d6;
  -webkit-text-fill-color: #b794d6;
}
.hero-scene {
  aspect-ratio: 1044 / 462;
  min-height: 640px;
  background:
    radial-gradient(ellipse at 98% 4%, #73139455, transparent 25%),
    radial-gradient(ellipse at 4% 65%, #451b7555, transparent 22%);
}
.hero-environment {
  z-index: 0;
}
.hero-horizon {
  top: 72%;
  opacity: 0.5;
}
.hero-grid {
  opacity: 0.5;
}
.hero-scene .circuit-copy {
  position: absolute;
  inset: 20% auto auto 10%;
  width: 44%;
  z-index: 3;
  text-align: left;
}
.hero-scene .circuit-eyebrow {
  position: static;
  width: auto;
  font-size: clamp(10px, 0.75vw, 13px);
  margin: 0 0 10px;
  text-align: left;
  letter-spacing: 0.2em;
}
.hero-scene .circuit-eyebrow > span {
  display: none;
}
.hero-scene .circuit-copy h1 {
  position: static;
  width: auto;
  margin: 0;
  font-size: clamp(44px, 5.25vw, 86px);
  line-height: 0.98;
  letter-spacing: -0.045em;
  text-align: left;
}
.hero-scene .circuit-description {
  position: static;
  width: 80%;
  margin: 20px 0 0;
  font-size: clamp(15px, 1.38vw, 22px);
  line-height: 1.3;
  text-align: left;
}
.hero-scene .circuit-actions {
  position: static;
  display: flex;
  justify-content: flex-start;
  margin: 22px 0 0;
  gap: 14px;
}
.hero-scene .circuit-actions a {
  position: static;
  width: auto;
  height: auto;
  min-height: 46px;
  font-size: clamp(12px, 1vw, 16px);
  padding: 12px 18px;
  border-radius: 6px;
  gap: 16px;
}
.hero-facts {
  display: flex;
  gap: 22px;
  margin-top: 22px;
}
.hero-facts p {
