  border: 0;
}
.hero-side-right::after {
  display: none;
}
.reference-signals {
  top: 56%;
  height: 42%;
  opacity: 0.9;
}
.hero-scene .circuit-stage {
  position: absolute;
  inset: auto 3% 5%;
  width: 94%;
  height: 16%;
  min-height: 0;
  margin: 0;
  padding: 0;
  z-index: 4;
}
.hero-scene .circuit-tiles {
  position: static;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 22px;
  padding: 0;
  height: 100%;
}
.hero-scene .circuit-stage .circuit-tile {
  position: relative;
  left: auto !important;
  top: auto !important;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 14px 30px 14px 14px;
  background: #101325;
  border: 1px solid #8664c5;
  border-radius: 10px;
  box-shadow:
    inset 0 -2px 3px #ad79ff,
    0 5px 14px #a84dff33;
  display: flex;
  align-items: center;
  gap: 10px;
  filter: brightness(var(--tile-brightness, 1));
  transform: rotate(2deg);
}
.hero-scene .circuit-tile:nth-child(even) {
  transform: rotate(-2deg);
}
.hero-scene .circuit-tile:last-child {
  border-color: #48d9eb;
  box-shadow:
    inset 0 -2px 3px #48d9eb,
    0 5px 14px #48d9eb22;
}
.hero-scene .circuit-tile::before {
  display: none;
}
.hero-scene .circuit-stage .circuit-tile img {
  position: static;
  width: 30%;
  height: 58px;
  transform: none;
  object-fit: contain;
}
.hero-scene .circuit-stage .circuit-tile span {
  position: static;
  width: auto;
  transform: none;
  font-size: 10px;
