}
.hero-scene .circuit-tile small {
  display: block;
  font-size: 10px;
}
.circuit-tile i {
  position: absolute;
  right: 8px;
  top: 40%;
  border: 1px solid #9577c8;
  border-radius: 50%;
  font-style: normal;
  color: #eee3ff;
  width: 22px;
  height: 22px;
  line-height: 20px;
  text-align: center;
  box-shadow: inset 0 0 8px #b877ff66;
}
.workflow-scene {
  position: absolute;
  left: 47%;
  right: 3%;
  top: 19%;
  height: 60%;
  pointer-events: none;
  color: #f4efff;
  z-index: 2;
}
.workflow-trails {
  position: absolute;
  inset: -8% -10%;
  width: 120%;
  height: 116%;
  overflow: visible;
  fill: none;
}
.workflow-trails path {
  stroke: url(#trail-color);
  stroke-width: 2;
}
.workflow-trails .trail-halo {
  stroke-width: 9;
  filter: url(#trail-glow);
  opacity: 0.7;
}
[data-workflow-dot] {
  fill: #e5fcff;
  filter: drop-shadow(0 0 6px #34dcff);
}
.workflow-pillars {
  display: flex;
  gap: 30px;
  position: absolute;
  left: 12%;
  top: 0;
}
.workflow-pillars > div {
  text-align: center;
}
.workflow-pillars b {
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  border: 2px solid #6c88ff;
  background: #111844;
  box-shadow:
    0 0 12px #5154ff,
    inset 0 0 12px #634aff;
