}
.workflow-pillars span {
  display: block;
  font-size: 10px;
  margin-top: 8px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.readiness-panel,
.throughput-panel,
.truth-panel {
  position: absolute;
  border: 1px solid #537ade;
  border-radius: 8px;
  background: #0c142cf5;
  box-shadow:
    inset 0 0 14px #5260ff33,
    0 0 12px #7648ff44;
  padding: 13px;
}
