  transform: rotate(4deg);
  filter: drop-shadow(0 0 7px #9b39ff);
}
.workflow-steps > div {
  flex: 1;
  text-align: center;
  padding: 12px 8px 16px;
  background: linear-gradient(135deg, #7632ab, #22173e 40%, #111526);
