      rotateX(var(--card-tilt, 12deg));
  }
  .hero-scene .circuit-stage .circuit-tile img {
    width: 36px;
    height: 40px;
  }
}
.hero-scene .circuit-tile {
  --card-lift: 0px;
  --card-tilt: 16deg;
}
@media (max-width: 900px) {
  .hero-scene .circuit-tile {
    --card-tilt: 12deg;
  }
}

/* Screenshot-matched desktop proportions, 1495 × 773 reference. */
