    margin-block: 5px;
  }
  .hero-scene .circuit-tile small {
    font-size: 12px;
  }
  .hero-scene .circuit-tile i {
    width: 27px;
    height: 27px;
    line-height: 25px;
    right: 12px;
  }
}
@media (min-width: 901px) {
  .hero-scene .circuit-copy {
    top: 19.6%;
  }
  .hero-scene .circuit-description {
    margin-top: 17px;
  }
  .hero-atmosphere > path:nth-child(2),
  .hero-atmosphere > path:nth-child(5) {
    transform: translateX(175px);
  }
  .hero-atmosphere > path:nth-child(1),
  .hero-atmosphere > path:nth-child(4) {
    transform: scaleX(1.15);
    transform-origin: left top;
  }
}
/* Keep every stage visible in the desktop viewport. */
@media (min-width: 901px) {
  .hero-scene .circuit-stage {
    left: 3.5%;
    right: 3.5%;
    width: 93%;
  }
  .hero-scene .circuit-tiles {
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: clamp(12px, 1.6vw, 26px);
    overflow: visible;
  }
  .hero-scene .circuit-stage .circuit-tile {
    width: 100%;
    min-width: 0;
    height: clamp(100px, 8.6vw, 140px);
    padding: 12px 30px 12px 12px;
  }
  .hero-scene .circuit-stage .circuit-tile img {
    width: 25%;
    height: 54px;
  }
  .hero-scene .circuit-tile strong {
    font-size: clamp(12px, 1.05vw, 16px);
  }
  .hero-scene .circuit-tile small {
    font-size: clamp(10px, 0.78vw, 12px);
  }
  .hero-scene .circuit-tile i {
    right: 6px;
    width: 22px;
    height: 22px;
    line-height: 20px;
  }
}

/* Consistent local perspective keeps the visible gaps equal across the row. */
@media (min-width: 901px) {
  .hero-scene .circuit-stage {
    perspective: none;
  }
  .hero-scene .circuit-stage .circuit-tile,
  .hero-scene .circuit-stage .circuit-tile:nth-child(even) {
    transform: perspective(850px) translateY(var(--card-lift, 0px))
      rotateX(var(--card-tilt, 16deg));
  }
}
.hero-scene .circuit-stage .circuit-tile {
  transition:
    border-color 300ms ease,
    box-shadow 300ms ease;
}
.hero-scene .circuit-stage .circuit-tile:is(:hover, :focus-visible) {
  --card-edge: #a8f0bf;
  border-color: #c2ffd5;
  box-shadow:
    inset 0 2px 3px #c2ffd566,
    inset -2px -2px 5px #02040c,
    0 3px 0 #294735,
    0 6px 0 #3f7252,
    0 8px 0 var(--card-edge),
    0 11px 0 #162d20,
    0 18px 20px #0009,
    0 0 20px #a8f0bf77,
    0 8px 34px #a8f0bf44;
}
@media (prefers-reduced-motion: reduce) {
  .hero-scene .circuit-stage .circuit-tile {
    transition: none;
  }
}

#contact { background: #f1edf4; color: #352c3d; }
#contact .contact-layout {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
  gap: clamp(32px, 6vw, 90px); align-items: start;
}
#contact h2 { color: #352c3d; font-size: clamp(36px, 4vw, 58px); }
#contact .eyebrow { color: #7a2c82; }
#contact p, #contact .contact-form-note a { color: #51455b; }
#contact .contact-form-note a { text-decoration: underline; }
#contact .contact-form-shell .button:disabled { opacity: 1; background: #67596e; cursor: not-allowed; }
.contact-fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 22px; }
.contact-fields label { display: grid; gap: 8px; font-size: 15px; font-weight: 700; }
.contact-wide { grid-column: 1 / -1; }
.contact-fields input, .contact-fields textarea {
  display: block; width: 100%; min-width: 0; box-sizing: border-box;
  border: 1px solid #a797af; border-radius: 3px; padding: 13px 14px;
  background: #fff; color: #352c3d; font: inherit; font-size: 16px; font-weight: 400;
}
.contact-fields textarea { resize: vertical; min-height: 140px; }
.contact-fields :is(input, textarea):focus-visible { outline: 3px solid #7a2c82; outline-offset: 3px; }
#contact .contact-form-shell .button { background: #7a2c82; color: #fff; margin-top: 18px; min-height: 48px; }
.contact-form-note, .contact-status { font-size: 14px; line-height: 1.5; margin-top: 16px; }
.contact-status:empty { display: none; }
@media (max-width: 900px) {
  #contact .contact-layout { grid-template-columns: 1fr; }
}
@media (max-width: 480px) {
  .contact-fields { grid-template-columns: 1fr; }
  #contact .contact-form-shell .button { width: 100%; justify-content: center; }
}

/* Shared page rhythm; the existing colours, type and content remain authoritative. */
:root {
  --page-gutter: clamp(20px, 4vw, 56px);
  --page-width: 1240px;
  --section-space: 80px;
  --column-space: 64px;
  --group-space: 32px;
}
.container,
.site-header .nav {
  width: min(var(--page-width), calc(100% - var(--page-gutter) * 2));
  margin-inline: auto;
}
.site-header {
  height: auto;
}
.site-header .nav {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  height: 88px;
}
.site-header .brand {
  position: relative;
  inset: auto;
  flex: 0 0 auto;
  width: 225px;
  height: auto;
}
.site-header .brand img {
  display: block;
  width: 100%;
  height: auto;
}
.site-header .desktop-nav {
  display: flex;
  gap: 24px;
  align-items: center;
}
.site-header .desktop-nav a,
.site-header .nav-contact {
  position: static;
  width: auto;
  height: auto;
  min-height: 44px;
  font-size: 14px;
  white-space: nowrap;
}
.site-header .desktop-nav a:nth-child(n) {
  width: auto;
}
.site-header .nav-contact {
  padding: 12px 20px;
}
.site-header .menu-toggle {
  flex-shrink: 0;
  width: 44px;
  height: 44px;
}
.hero.circuit-hero,
.hero-scene {
  aspect-ratio: auto;
}
.hero-scene {
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 144px max(var(--page-gutter), calc((100% - var(--page-width)) / 2))
    32px;
  gap: 80px;
}
.hero-scene .circuit-copy {
  position: relative;
  inset: auto;
  width: min(680px, 100%);
  margin: 0;
  padding: 0;
}
.hero-scene .circuit-description {
  width: 100%;
  max-width: 520px;
  line-height: 1.5;
}
.hero-scene .circuit-actions {
  gap: 16px;
  flex-wrap: wrap;
}
.hero-scene .circuit-actions a {
  min-height: 48px;
  padding: 12px 20px;
  font-size: 14px;
}
.hero-scene .circuit-stage {
  position: relative;
  inset: auto;
  width: 100%;
  height: auto;
  perspective: none;
}
.hero-scene .circuit-tiles {
  padding: 8px 0 20px;
  gap: 24px;
}
.hero-scene .circuit-stage .circuit-tile {
  min-width: 0;
}
.hero-scene .circuit-tile i {
  top: 50%;
  transform: translateY(-50%);
}
.finder-section,
.services,
.brief-section,
#method,
.analysis-examples,
#about,
.industry,
#contact {
  padding-block: var(--section-space);
}
.finder-layout,
.brief-layout,
#about,
.industry-layout,
#contact .contact-layout {
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
  gap: var(--column-space);
  align-items: start;
}
.brief-copy {
  padding-top: 0;
}
.finder-layout > *,
.brief-layout > *,
#about > *,
.industry-layout > *,
.contact-layout > * {
  min-width: 0;
}
.finder-choices > a:hover {
  transform: none;
}
.service-grid,
.analysis-grid {
  margin-top: var(--group-space);
}
.service-card {
  column-gap: 24px;
  padding-block: 32px;
}
.method-steps {
  margin-block: var(--group-space);
  gap: 16px 40px;
}
.method-steps li {
  display: grid;
  grid-template-rows: subgrid;
  grid-row: span 3;
  padding: 0;
}
.method-steps .engagement-number,
.method-steps h3,
.method-steps p {
  margin: 0;
}
.method-steps .engagement-number {
  justify-self: start;
}
.analysis-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--group-space);
}
.analysis-example:nth-child(2) {
  margin: 0;
  max-width: none;
}
.analysis-image {
  padding: 16px;
}
.analysis-image img {
  width: 100%;
  height: auto;
  aspect-ratio: 16 / 9;
  object-fit: contain;
}
.analysis-example figcaption {
  padding: 24px 0 0;
  max-width: none;
}
.analysis-source {
  margin-top: var(--group-space);
}
.philosophy {
  padding-block: 48px;
}
.philosophy-inner {
  max-width: var(--page-width);
}
.contact-fields {
  gap: 24px;
}
#contact .contact-form-shell > .contact-form-note {
  max-width: none;
  margin-top: 16px;
  font-size: 14px;
  line-height: 1.6;
}
.footer-top {
  gap: 32px;
  align-items: center;
}
.footer-bottom {
  gap: 24px;
  align-items: center;
}
@media (max-width: 1100px) {
  .site-header .desktop-nav {
    display: none !important;
  }
  .site-header .menu-toggle {
    display: flex;
  }
  .site-header .nav-contact {
    margin-left: auto;
  }
  #mobile-nav:not([hidden]) {
    display: block;
  }
  #mobile-nav {
    padding-inline: var(--page-gutter);
  }
}
@media (max-width: 900px) {
  :root {
    --section-space: 64px;
    --column-space: 32px;
  }
  .hero-scene {
    padding-top: 40px;
    padding-bottom: 32px;
    gap: 32px;
  }
  .finder-layout,
  .brief-layout,
  #about,
  .industry-layout,
  #contact .contact-layout {
    grid-template-columns: minmax(0, 1fr);
  }
  .analysis-grid {
    grid-template-columns: minmax(0, 1fr);
    gap: 40px;
  }
  .hero-scene .circuit-stage .circuit-tile,
  .hero-scene .circuit-stage .circuit-tile:nth-child(even) {
    height: 80px;
  }
}
@media (max-width: 700px) {
  .method-steps {
    gap: 32px;
  }
  .method-steps li {
    grid-row: auto;
    grid-template-columns: 24px minmax(0, 1fr);
    grid-template-rows: auto auto;
    gap: 8px 16px;
  }
  .method-steps .engagement-number {
    position: static;
    grid-row: 1 / 3;
    align-self: start;
  }
  .method-steps h3,
  .method-steps p {
    grid-column: 2;
  }
}
@media (max-width: 600px) {
  :root {
    --section-space: 48px;
    --group-space: 32px;
  }
  .site-header .nav {
    height: 80px;
  }
  .site-header .brand {
    width: 200px;
  }
  .site-header .nav-contact {
    display: none;
  }
  .hero-scene .circuit-copy h1 {
    font-size: clamp(38px, 10vw, 54px);
  }
  .hero-scene .circuit-actions {
    display: grid;
    grid-template-columns: 1fr;
  }
  .hero-scene .circuit-actions a {
    width: 100%;
    justify-content: space-between;
  }
  .service-card {
    padding-block: 24px;
  }
  .philosophy {
    padding-block: 40px;
  }
  .footer-top nav {
    gap: 8px 24px;
  }
}
@media (max-width: 360px) {
  .site-header .brand {
    width: 176px;
  }
}

/* Supplied stacked master logo: retain the full artwork and its proportions. */
.site-header .nav {
  height: 112px;
}
.site-header .brand {
  width: 112px;
}
.site-header .brand img {
  width: 112px;
  height: 112px;
  object-fit: contain;
}
.footer-top .brand img {
  width: 180px;
  height: 180px;
  object-fit: contain;
  filter: none;
  background: #fff;
  border-radius: 8px;
}
.site-header .brand img {
  filter: none;
  background: #fff;
  border-radius: 8px;
}
